files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2d2d44;
  --text: #f0e6d2;
  --accent: #f2a65a;
  --accent-hover: #ffb86b;
  --accent-pressed: #d98c3f;
  --available: #6fcf97;
  --checked: #eb5757;
  --focus: #f2a65a;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.desk-card {
  background: var(--card-bg);
  border: 4px solid var(--accent);
  border-radius: 8px;
  padding: 24px 20px;
  max-width: 600px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  margin: 0 0 8px;
  font-size: 1.8rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 24px;
  font-size: 1rem;
  opacity: 0.8;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.filter-label {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  font-size: 1rem;
}

.filter-label input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
}

.filter-label input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.count {
  font-weight: bold;
  background: var(--bg);
  padding: 6px 12px;
  border-radius: 4px;
  font-size: 1rem;
  border: 2px solid var(--accent);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.book-item {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--bg);
  padding: 12px 16px;
  border-radius: 4px;
  border: 2px solid transparent;
}

.book-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1 1 140px;
}

.book-title {
  font-weight: bold;
  font-size: 1.1rem;
}

.book-status {
  font-size: 0.9rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.book-status.available {
  color: var(--available);
}

.book-status.checked {
  color: var(--checked);
}

.book-action {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 8px 16px;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  background: var(--accent);
  color: var(--bg);
  min-width: 110px;
  transition: background 0.15s, transform 0.1s;
}

.book-action:hover {
  background: var(--accent-hover);
}

.book-action:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.book-action:active {
  background: var(--accent-pressed);
  transform: translateY(2px);
}

@media (max-width: 400px) {
  body {
    font-size: 16px;
    padding: 8px;
  }
  .desk-card {
    padding: 16px 12px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .book-item {
    padding: 10px 12px;
  }
  .book-action {
    min-width: 90px;
    padding: 6px 12px;
  }
}

const books = [
  { id: 1, title: 'The Pixel Frontier', checkedOut: false },
  { id: 2, title: 'CSS: A Visual Guide', checkedOut: false },
  { id: 3, title: 'JavaScript Patterns', checkedOut: true },
  { id: 4, title: 'Designing with Grid', checkedOut: false },
  { id: 5, title: 'The Art of Color', checkedOut: true },
  { id: 6, title: 'Accessible Interfaces', checkedOut: false }
];

const bookList = document.getElementById('bookList');
const filterCheckbox = document.getElementById('filterAvailable');
const countDisplay = document.getElementById('checkedOutCount');

function render() {
  const showAvailableOnly = filterCheckbox.checked;
  bookList.innerHTML = '';

  books.forEach(book => {
    if (showAvailableOnly && book.checkedOut) return;

    const li = document.createElement('li');
    li.className = 'book-item';

    const info = document.createElement('div');
    info.className = 'book-info';

    const title = document.createElement('span');
    title.className = 'book-title';
    title.textContent = book.title;

    const status = document.createElement('span');
    status.className = 'book-status ' + (book.checkedOut ? 'checked' : 'available');
    status.textContent = book.checkedOut ? 'Checked out' : 'Available';

    info.appendChild(title);
    info.appendChild(status);

    const btn = document.createElement('button');
    btn.className = 'book-action';
    btn.textContent = book.checkedOut ? 'Return' : 'Check out';
    btn.setAttribute('aria-label', (book.checkedOut ? 'Return ' : 'Check out ') + book.title);
    btn.addEventListener('click', () => {
      book.checkedOut = !book.checkedOut;
      render();
    });

    li.appendChild(info);
    li.appendChild(btn);
    bookList.appendChild(li);
  });

  const checkedCount = books.filter(b => b.checkedOut).length;
  countDisplay.textContent = 'Checked out: ' + checkedCount;
}

filterCheckbox.addEventListener('change', render);

render();
